# Surah Fussilat (chapter 41) — part 5: ayat 49-54 (IDs 4267-4272)
SURAH = 41

ENTRIES = {
4267: (
"انسان بھلائی کی دعا سے اکتاتا نہیں — اور اگر اسے برائی پہنچتی ہے تو مایوس اور ناامید ہو جاتا ہے",
"""۱۔ انسان کی فطرت — لا یسأم الإنسان من دعاء الخیر؛ مسّہ الشر؛ فیئوس قنوط۔
۲۔ ’’لَّا يَسْأَمُ الْإِنسَانُ مِن دُعَاءِ الْخَيْرِ وَإِن مَّسَّهُ الشَّرُّ فَيَئُوسٌ قَنُوطٌ‘‘ — انسان بھلائی کی دعا سے اکتاتا نہیں — اور اگر اسے برائی پہنچتی ہے تو مایوس اور ناامید ہو جاتا ہے — یعنی انسان بھلائی کی دعا سے اکتاتا نہیں اور اگر اسے برائی پہنچتی ہے تو مایوس اور ناامید ہو جاتا ہے۔
۳۔ عملی سبق: دعا سے اکتاؤ نہ؛ تنگی میں صبر کرو؛ اللہ سے ڈرو۔"""
),
4268: (
"اور اگر ہم اسے تکلیف کے بعد اپنی رحمت چکھائیں تو وہ کہتا یہ تو میرے لیے ہے — اور میں نہیں سمجھتا کہ قیامت قائم ہونے والی ہے — اور اگر میں اپنے رب کی طرف لوٹایا گیا تو یقیناً میرے لیے اس کے ہاں بہترین بدلہ ہوگا — پس ہم کافروں کو ان کے اعمال کی خبر دیں گے اور انہیں سخت عذاب چکھائیں گے",
"""۱۔ رحمت کے بعد دعوٰی — أذقناه رحمةً؛ هذا لی؛ ما أظن الساعة قائمةً؛ للکافرون عذاب غلیظ۔
۲۔ ’’وَلَئِنْ أَذَقْنَاهُ رَحْمَۃً مِّنَّا مِن بَعْدِ ضَرَّاءَ مَسَّتْهُ لَيَقُولَنَّ هَٰذَا لِي وَمَا أَظُنُّ السَّاعَۃَ قَائِمَۃً وَلَئِن رُّجِعْتُ إِلَىٰ رَبِّي إِنَّ لِي عِندَهُ لَلْحُسْنَىٰ فَلَنُنَبِّئَنَّ الَّذِينَ كَفَرُوا بِمَا عَمِلُوا وَلَنُذِيقَنَّهُم مِّنْ عَذَابٍ غَلِيظٍ‘‘ — اور اگر ہم اسے تکلیف کے بعد اپنی رحمت چکھائیں تو وہ کہتا یہ تو میرے لیے ہے — اور میں نہیں سمجھتا کہ قیامت قائم ہونے والی ہے — اور اگر میں اپنے رب کی طرف لوٹایا گیا تو یقیناً میرے لیے اس کے ہاں بہترین بدلہ ہوگا — پس ہم کافروں کو ان کے اعمال کی خبر دیں گے اور انہیں سخت عذاب چکھائیں گے — یعنی اور اگر ہم اسے تکلیف کے بعد اپنی رحمت چکھائیں تو وہ کہتا یہ تو میرے لیے ہے اور میں نہیں سمجھتا کہ قیامت قائم ہونے والی ہے اور اگر میں اپنے رب کی طرف لوٹایا گیا تو یقیناً میرے لیے اس کے ہاں بہترین بدلہ ہوگا پس ہم کافروں کو ان کے اعمال کی خبر دیں گے اور انہیں سخت عذاب چکھائیں گے۔
۳۔ عملی سبق: نعمت ملنے پر احسان نہ کرو؛ قیامت کو یاد رکھو؛ اللہ سے ڈرو۔"""
),
4269: (
"اور جب ہم انسان پر نعمت کرتے ہیں تو وہ منہ موڑتا اور کروٹ بدل کر دوری اختیار کرتا ہے — اور جب اسے برائی پہنچتی ہے تو لمبا چوڑا ہو کر دعا کرنے لگتا ہے",
"""۱۔ انسان کی عادت — أعرض و نأی بجانبه؛ مسّه الشر؛ فذو دعاء عریض۔
۲۔ ’’وَإِذَا أَنْعَمْنَا عَلَى الْإِنسَانِ أَعْرَضَ وَنَأَىٰ بِجَانِبِهِ وَإِذَا مَسَّهُ الشَّرُّ فَذُو دُعَاءٍ عَرِيضٍ‘‘ — اور جب ہم انسان پر نعمت کرتے ہیں تو وہ منہ موڑتا اور کروٹ بدل کر دوری اختیار کرتا ہے — اور جب اسے برائی پہنچتی ہے تو لمبا چوڑا ہو کر دعا کرنے لگتا ہے — یعنی اور جب ہم انسان پر نعمت کرتے ہیں تو وہ منہ موڑتا اور کروٹ بدل کر دوری اختیار کرتا ہے اور جب اسے برائی پہنچتی ہے تو لمبا چوڑا ہو کر دعا کرنے لگتا ہے۔
۳۔ عملی سبق: نعمت میں شکر اور سختی میں صبر کرو؛ اللہ سے ڈرو۔"""
),
4270: (
"کہہ دیجیے کیا تم نے دیکھا اگر یہ (قرآن) اللہ کی طرف سے ہو پھر تم نے اس سے کفر کیا — تو اس سے زیادہ گمراہ کون ہے جو دور کی مخالفت میں پڑا ہو",
"""۱۔ قرآن کی صداقت — إن کان من عند اللہ ثم کفرتم به؛ من أضل ممن هو في شقاق بعید۔
۲۔ ’’قُلْ أَرَأَيْتُمْ إِن كَانَ مِنْ عِندِ اللَّهِ ثُمَّ كَفَرْتُم بِهِ مَنْ أَضَلُّ مِمَّنْ هُوَ فِي شِقَاقٍ بَعِيدٍ‘‘ — کہہ دیجیے کیا تم نے دیکھا اگر یہ (قرآن) اللہ کی طرف سے ہو پھر تم نے اس سے کفر کیا — تو اس سے زیادہ گمراہ کون ہے جو دور کی مخالفت میں پڑا ہو — یعنی کہہ دیجیے کیا تم نے دیکھا اگر یہ (قرآن) اللہ کی طرف سے ہو پھر تم نے اس سے کفر کیا تو اس سے زیادہ گمراہ کون ہے جو دور کی مخالفت میں پڑا ہو۔
۳۔ عملی سبق: قرآن کو اللہ کا کلام مانو؛ مخالفت سے بچو؛ اللہ سے ڈرو۔"""
),
4271: (
"ہم عنقریب انہیں اپنی نشانیاں آفاق میں اور خود ان کے اندر دکھائیں گے یہاں تک کہ ان پر یہ بات کھل جائے کہ یہ حق ہے — کیا تمہارے رب کے لیے یہ کافی نہیں کہ وہ ہر چیز کا گواہ ہے",
"""۱۔ نشانیاں — سنریهم آیاتنا في الآفاق و في أنفسهم؛ حتی یتبين لهم أنه الحق؛ أولم یکف بربک أنه علی کل شیء شہید۔
۲۔ ’’سَنُرِيهِمْ آيَاتِنَا فِي الْآفَاقِ وَفِي أَنفُسِهِمْ حَتَّىٰ يَتَبَيَّنَ لَهُمْ أَنَّهُ الْحَقُّ أَوَلَمْ يَكْفِ بِرَبِّكَ أَنَّهُ عَلَىٰ كُلِّ شَيْءٍ شَهِيدٌ‘‘ — ہم عنقریب انہیں اپنی نشانیاں آفاق میں اور خود ان کے اندر دکھائیں گے یہاں تک کہ ان پر یہ بات کھل جائے کہ یہ حق ہے — کیا تمہارے رب کے لیے یہ کافی نہیں کہ وہ ہر چیز کا گواہ ہے — یعنی ہم عنقریب انہیں اپنی نشانیاں آفاق میں اور خود ان کے اندر دکھائیں گے یہاں تک کہ ان پر یہ بات کھل جائے کہ یہ حق ہے کیا تمہارے رب کے لیے یہ کافی نہیں کہ وہ ہر چیز کا گواہ ہے۔
۳۔ عملی سبق: آفاق اور اپنی ذات میں اللہ کی نشانیاں دیکھو؛ اللہ سے ڈرو۔"""
),
4272: (
"آگاہ ہو جاؤ وہ اپنے رب سے ملاقات میں شک میں ہیں — آگاہ ہو جاؤ بے شک وہ ہر چیز پر محیط ہے",
"""۱۔ شک اور احاطہ — أالا إنهم في مرية من لقاء ربهم؛ ألا إنه بکل شیء محیط۔
۲۔ ’’أَلَا إِنَّهُمْ فِي مِرْيَۃٍ مِّن لِّقَاءِ رَبِّهِمْ أَلَا إِنَّهُ بِكُلِّ شَيْءٍ مُّحِيطٌ‘‘ — آگاہ ہو جاؤ وہ اپنے رب سے ملاقات میں شک میں ہیں — آگاہ ہو جاؤ بے شک وہ ہر چیز پر محیط ہے — یعنی آگاہ ہو جاؤ وہ اپنے رب سے ملاقات میں شک میں ہیں آگاہ ہو جاؤ بے شک وہ ہر چیز پر محیط ہے۔
۳۔ عملی سبق: رب کی ملاقات پر یقین رکھو؛ اللہ سے ڈرو۔"""
),
}
